<script>
document.getElementById('teacher-grade').closest('label').childNodes[0].nodeValue='Assigned grade';
const placementOptions=<?= json_encode($placement) ?>,subjectOptions=<?= json_encode(teacherSubjects()) ?>,gradeSelect=document.getElementById('teacher-grade'),assignmentSelect=document.getElementById('teacher-assignment'),assignmentLabel=document.getElementById('assignment-label'),sectionSelect=document.getElementById('teacher-section');
function setOptions(select,placeholder,items){select.innerHTML='';select.add(new Option(placeholder,''));items.forEach(item=>select.add(new Option(item,item)))}
function updateTeacherPlacement(){const grade=gradeSelect.value,senior=grade==='11'||grade==='12';assignmentLabel.textContent=senior?'Strand assigned':'Subject assigned';assignmentSelect.name=senior?'strand':'subject';assignmentSelect.disabled=!grade;setOptions(assignmentSelect,grade?(senior?'Choose a strand':'Choose a subject'):'Choose a grade first',senior?['Techpro','Academic']:subjectOptions);if(!grade){setOptions(sectionSelect,'Choose a grade first',[]);sectionSelect.disabled=true;return}if(senior){setOptions(sectionSelect,'Choose a strand first',[]);sectionSelect.disabled=true}else{setOptions(sectionSelect,'Choose a section',placementOptions[grade]||[]);sectionSelect.disabled=false}}
function updateTeacherSections(){const grade=gradeSelect.value;if(!(grade==='11'||grade==='12'))return;setOptions(sectionSelect,assignmentSelect.value?'Choose a section':'Choose a strand first',placementOptions[grade]?.[assignmentSelect.value]||[]);sectionSelect.disabled=!assignmentSelect.value}
gradeSelect.onchange=updateTeacherPlacement;assignmentSelect.onchange=updateTeacherSections;updateTeacherPlacement();document.querySelector('form').onsubmit=e=>{if(document.getElementById('teacher-pass').value!==document.getElementById('teacher-confirm').value){e.preventDefault();alert('Passwords do not match.')}};
</script>
